    string smallestSubsequence(string s, int k, char letter, int repetition) {
        int rem_letters = 0;
        for (char c : s) if (c == letter) rem_letters++;
        string stack = "";
        int n = s.size();
        for (int i = 0; i < n; ++i) {
            char c = s[i];
            while (!stack.empty() && stack.back() > c && ((int)stack.size() + (n - i) > k)) {
                if (stack.back() == letter) {
                    if (rem_letters <= repetition) break;
                    repetition++;
                }
                stack.pop_back();
            }
