class Solution {
    public String smallestSubsequence(String s, int k, char letter, int repetition) {
        int remLetters = 0;
        for (char c : s.toCharArray()) if (c == letter) remLetters++;
        StringBuilder stack = new StringBuilder();
        int n = s.length();
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            while (stack.length() > 0 && stack.charAt(stack.length() - 1) > c && (stack.length() + (n - i) > k)) {
                if (stack.charAt(stack.length() - 1) == letter) {
                    if (remLetters <= repetition) break;
                    repetition++;
                }
                stack.deleteCharAt(stack.length() - 1);
            }
            if (stack.length() < k) {
                if (c == letter) {
                    stack.append(c);
                    repetition--;
                } else if (k - stack.length() > repetition) {
                    stack.append(c);
                }
            }
            if (c == letter) remLetters--;
        }
        return stack.toString();
    }
}

var smallestSubsequence = function(s, k, letter, repetition) {
  let remLetters = 0;
  for (const c of s) if (c === letter) remLetters++;
  const stack = [];
  const n = s.length;
  for (let i = 0; i < n; i++) {
    const c = s[i];
    while (stack.length > 0 && stack[stack.length - 1] > c && (stack.length + (n - i) > k)) {
      if (stack[stack.length - 1] === letter) {
        if (remLetters <= repetition) break;
        repetition++;
      }
      stack.pop();
    }
    if (stack.length < k) {
      if (c === letter) {
